1	//! Shared `Session` conformance suite (spec §5). Each backend supplies a
2	//! factory that yields a fresh, empty session; these functions exercise the
3	//! append/read/projection/concurrency contract every backend must uphold.
4	
5	use std::future::Future;
6	use std::sync::Arc;
7	
8	use jiff::Timestamp;
9	use paigasus_helikon_core::{ContentPart, Item, SequenceId, Session, SessionEvent};
10	
11	fn user(text: &str) -> SessionEvent {
12	    SessionEvent::UserMessage {
13	        content: vec![ContentPart::Text { text: text.into() }],
14	        ts: Timestamp::from_second(1_700_000_000).unwrap(),
15	    }
16	}
17	
18	/// Extract the text of a `UserMessage` event, panicking on any other shape.
19	/// Used by the assertions below to compare exact content and order.
20	fn event_text(ev: &SessionEvent) -> &str {
21	    match ev {
22	        SessionEvent::UserMessage { content, .. } => match content.first() {
23	            Some(ContentPart::Text { text }) => text.as_str(),
24	            other => panic!("expected leading Text content, got {other:?}"),
25	        },
26	        other => panic!("expected UserMessage, got {other:?}"),
27	    }
28	}
29	
30	/// Extract the text of a projected `Item::UserMessage`, panicking otherwise.
31	fn item_text(item: &Item) -> &str {
32	    match item {
33	        Item::UserMessage { content } => match content.first() {
34	            Some(ContentPart::Text { text }) => text.as_str(),
35	            other => panic!("expected leading Text content, got {other:?}"),
36	        },
37	        other => panic!("expected Item::UserMessage, got {other:?}"),
38	    }
39	}
40	
41	/// Append several events, read them back, assert order and count are preserved.
42	pub async fn run_append_read<F, Fut>(make: F)
43	where
44	    F: Fn() -> Fut,
45	    Fut: Future<Output = Arc<dyn Session>>,
46	{
47	    let s = make().await;
48	    s.append(&[user("a"), user("b"), user("c")]).await.unwrap();
49	    let got = s.events(None).await.unwrap();
50	    assert_eq!(got.len(), 3, "all appended events read back");
51	    // Assert exact content AND order, not just count: a backend that reordered
52	    // or corrupted payloads must fail here.
53	    let texts: Vec<&str> = got.iter().map(event_text).collect();
54	    assert_eq!(
55	        texts,
56	        ["a", "b", "c"],
57	        "events read back in exact append order with exact content"
58	    );
59	}
60	
61	/// `events(Some(SequenceId(n)))` is an exclusive watermark: returns positions > n.
62	pub async fn run_watermark_exclusive<F, Fut>(make: F)
63	where
64	    F: Fn() -> Fut,
65	    Fut: Future<Output = Arc<dyn Session>>,
66	{
67	    let s = make().await;
68	    for i in 0..5 {
69	        s.append(&[user(&format!("m{i}"))]).await.unwrap();
70	    }
71	    let after = s.events(Some(SequenceId(2))).await.unwrap();
72	    // Assert it returns exactly the right two events (positions 3 and 4) in
73	    // order — not merely "two events": a backend returning the wrong rows must fail.
74	    let texts: Vec<&str> = after.iter().map(event_text).collect();
75	    assert_eq!(
76	        texts,
77	        ["m3", "m4"],
78	        "exclusive watermark returns exactly positions 3 and 4, in order"
79	    );
80	}
81	
82	/// `snapshot()` equals `project(events())`.
83	pub async fn run_projection<F, Fut>(make: F)
84	where
85	    F: Fn() -> Fut,
86	    Fut: Future<Output = Arc<dyn Session>>,
87	{
88	    let s = make().await;
89	    s.append(&[user("p1"), user("p2")]).await.unwrap();
90	    let snap = s.snapshot().await.unwrap();
91	    let events = s.events(None).await.unwrap();
92	    let expected = paigasus_helikon_core::project(&events);
93	    assert_eq!(snap.messages.len(), expected.messages.len());
94	    assert_eq!(snap.messages.len(), 2);
95	    // Assert the projected snapshot preserves exact content and order, not just
96	    // length: a snapshot with the right count but wrong messages must fail.
97	    let texts: Vec<&str> = snap.messages.iter().map(item_text).collect();
98	    assert_eq!(
99	        texts,
100	        ["p1", "p2"],
101	        "snapshot() projects messages with exact content in order"
102	    );
103	}
104	
105	/// N tasks append concurrently to the same session; every event survives once.
106	pub async fn run_concurrent_writers<F, Fut>(make: F)
107	where
108	    F: Fn() -> Fut,
109	    Fut: Future<Output = Arc<dyn Session>>,
110	{
111	    const N_TASKS: usize = 16;
112	    const M_EVENTS: usize = 10;
113	    let session = make().await;
114	    let mut handles = Vec::new();
115	    for t in 0..N_TASKS {
116	        let s = session.clone();
117	        handles.push(tokio::spawn(async move {
118	            for j in 0..M_EVENTS {
119	                s.append(&[user(&format!("t{t}-m{j}"))]).await.unwrap();
120	            }
121	        }));
122	    }
123	    for h in handles {
124	        h.await.unwrap();
125	    }
126	    let all = session.events(None).await.unwrap();
127	    assert_eq!(
128	        all.len(),
129	        N_TASKS * M_EVENTS,
130	        "no lost or duplicated events"
131	    );
132	    let mut texts: Vec<String> = all
133	        .into_iter()
134	        .filter_map(|e| match e {
135	            SessionEvent::UserMessage { content, .. } => match content.into_iter().next() {
136	                Some(ContentPart::Text { text }) => Some(text),
137	                _ => None,
138	            },
139	            _ => None,
140	        })
141	        .collect();
142	    texts.sort();
143	    let mut expected: Vec<String> = (0..N_TASKS)
144	        .flat_map(|t| (0..M_EVENTS).map(move |j| format!("t{t}-m{j}")))
145	        .collect();
146	    expected.sort();
147	    assert_eq!(texts, expected, "every sent event present exactly once");
148	}
149	
150	/// Run the full conformance suite against `make`. `make` is invoked once per
151	/// sub-test and MUST return a fresh, empty session each time.
152	pub async fn run_all<F, Fut>(make: F)
153	where
154	    F: Fn() -> Fut,
155	    Fut: Future<Output = Arc<dyn Session>>,
156	{
157	    run_append_read(&make).await;
158	    run_watermark_exclusive(&make).await;
159	    run_projection(&make).await;
160	    run_concurrent_writers(&make).await;
161	}
